import { createWorker } from 'tesseract.js';

/**
 * Procesa imágenes en segundo plano sin bloquear el hilo principal de la UI.
 */
export async function processDocumentOcr(imageBlob, onProgress) {
  let worker = null;
  try {
    worker = await createWorker('spa');

    if (onProgress) {
      worker.logger = (m) => {
        if (m.status === 'recognizing text') {
          onProgress(Math.round(m.progress * 100));
        }
      };
    }

    const { data: { text, confidence } } = await worker.recognize(imageBlob);
    const sanitized = text.replace(/[
]+/g, '\n').trim();

    return {
      success: true,
      text: sanitized,
      confidence: Math.round(confidence)
    };
  } catch (error) {
    console.error('[OCR Worker] Fallo en procesamiento local:', error);
    return { success: false, error: error.message };
  } finally {
    if (worker) await worker.terminate(); // Libera recursos del navegador
  }
}

import axios from 'axios';
import * as cheerio from 'cheerio';
import { db } from '../database/sqlite.js';
import { sendTelegramAlert } from '../bot/telegram.js';

/**
 * Rastreo desatendido y detección de caídas reales de precio.
 */
export async function monitorCategoryOffers(categoryUrl) {
  try {
    const { data: html } = await axios.get(categoryUrl, {
      headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)' },
      timeout: 8000
    });

    const $ = cheerio.load(html);
    const products = [];

    $('.product-card').each((_, el) => {
      const sku = $(el).attr('data-sku');
      const title = $(el).find('.product-title').text().trim();
      const priceText = $(el).find('.price-current').text().replace(/\D/g, '');
      const price = parseInt(priceText, 10);

      if (sku && price > 0) products.push({ sku, title, price });
    });

    // Evalúa contra histórico para descartar falsas ofertas publicitarias
    for (const prod of products) {
      const avgPrice = await db.getHistoricalAverage(prod.sku);
      if (avgPrice && prod.price <= avgPrice * 0.70) {
        const dropPercent = Math.round(((avgPrice - prod.price) / avgPrice) * 100);
        await sendTelegramAlert({ ...prod, avgPrice, dropPercent });
      }
      await db.savePriceSample(prod.sku, prod.price);
    }
  } catch (err) {
    console.error('[Scraper Error]:', err.message);
  }
}

package com.campus.service;

import com.campus.model.RegistroAcceso;
import com.campus.model.Vehiculo;
import com.campus.repository.RegistroRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.LocalDateTime;

@Service
public class ControlVehicularService {

    private final RegistroRepository registroRepository;

    public ControlVehicularService(RegistroRepository registroRepository) {
        this.registroRepository = registroRepository;
    }

    /**
     * Registra ingreso con validación transaccional y prevención de duplicados
     */
    @Transactional
    public RegistroAcceso registrarEntrada(Vehiculo vehiculo) {
        String placaNormalizada = vehiculo.getPlaca().toUpperCase().trim();

        // Regla de negocio: validar que el vehículo no esté ya en las instalaciones
        boolean yaPresente = registroRepository.existeEntradaSinSalida(placaNormalizada);
        if (yaPresente) {
            throw new IllegalStateException("El vehículo " + placaNormalizada + " ya se encuentra dentro.");
        }

        RegistroAcceso nuevoRegistro = new RegistroAcceso();
        nuevoRegistro.setVehiculo(vehiculo);
        nuevoRegistro.setFechaHoraEntrada(LocalDateTime.now());
        nuevoRegistro.setEstado("ACTIVO");

        return registroRepository.save(nuevoRegistro);
    }
}

package com.tienda.patrones;

import java.util.concurrent.ConcurrentHashMap;
import java.util.Map;

/**
 * Singleton Thread-Safe con Double-Checked Locking para gestión de inventario central.
 */
public class InventarioSingleton {

    private static volatile InventarioSingleton instance;
    private final Map<String, Integer> stockPorDispositivo;

    private InventarioSingleton() {
        this.stockPorDispositivo = new ConcurrentHashMap<>();
    }

    public static InventarioSingleton getInstance() {
        if (instance == null) {
            synchronized (InventarioSingleton.class) {
                if (instance == null) {
                    instance = new InventarioSingleton();
                }
            }
        }
        return instance;
    }

    public synchronized boolean descontarStock(String idDispositivo, int cantidad) {
        int actual = stockPorDispositivo.getOrDefault(idDispositivo, 0);
        if (actual >= cantidad) {
            stockPorDispositivo.put(idDispositivo, actual - cantidad);
            return true;
        }
        return false;
    }
}
